using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.DependencyInjection;
using Shop.Modules.Cms;
using Shop.Modules.Identity;
using Shop.SharedKernel;
using Xunit;
namespace Shop.SqlTests;
public sealed class CmsRedirectSqlTests:IAsyncLifetime
{
    private readonly SqlFixture sql=new();private Microsoft.AspNetCore.Mvc.Testing.WebApplicationFactory<Program>? auth;public Task InitializeAsync()=>sql.InitializeAsync();public async Task DisposeAsync(){auth?.Dispose();await sql.DisposeAsync();}
    private static string Id()=>Guid.NewGuid().ToString("N");private static string S(JsonNode n,string key)=>n[key]!.GetValue<string>();
    private static async Task<JsonNode> Read(HttpResponseMessage r){using(r){var raw=await r.Content.ReadAsStringAsync();Assert.True(r.IsSuccessStatusCode,$"{(int)r.StatusCode}: {raw}");Assert.Contains("no-store",r.Headers.CacheControl!.ToString());var path=r.RequestMessage!.RequestUri!.PathAndQuery;if(path.StartsWith("/api/admin/redirects",StringComparison.Ordinal)){Assert.Contains("private",r.Headers.CacheControl.ToString());Assert.Contains("noindex",r.Headers.GetValues("X-Robots-Tag").Single());}if(Environment.GetEnvironmentVariable("SHOP_CMS_REDIRECTS_WIRE_DIR")is{Length:>0}dir&&path.Contains("/redirects",StringComparison.Ordinal)){Directory.CreateDirectory(dir);var id=Id();await File.WriteAllTextAsync(System.IO.Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(System.IO.Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{syntheticQaOnly=true,actualSqlHttpResponse=true,status=(int)r.StatusCode,method=r.RequestMessage.Method.Method,path}));}return JsonNode.Parse(raw)!;}}
    private async Task<HttpClient> Staff(string role="ContentManager"){
        await using var scope=sql.Factory.Services.CreateAsyncScope();var users=scope.ServiceProvider.GetRequiredService<UserManager<ShopUser>>();var name="redirectqa"+Id();var u=new ShopUser{UserName=name,Email=name+"@example.test",EmailConfirmed=true,RequireMfa=true};Assert.True((await users.CreateAsync(u,sql.Password)).Succeeded);Assert.True((await users.AddToRoleAsync(u,role)).Succeeded);var c=(auth??=sql.Factory.WithWebHostBuilder(_=>{})).CreateClient(new(){HandleCookies=false});c.DefaultRequestHeaders.Add("Origin","http://127.0.0.1:3173");c.DefaultRequestHeaders.Add("X-Sayman-Client","admin");c.DefaultRequestHeaders.Add("X-Sayman-Admin","1");var p=await Read(await c.PostAsJsonAsync("/api/auth/password",new{Identifier=name,Password=sql.Password}));c.DefaultRequestHeaders.Authorization=new("Bearer",S(p,"accessToken"));var setup=await Read(await c.PostAsJsonAsync("/api/auth/mfa/setup",new{}));c.DefaultRequestHeaders.Authorization=new("Bearer",S(setup,"accessToken"));var signed=await Read(await c.PostAsJsonAsync("/api/auth/mfa/verify",new{Code=Totp.Code(S(setup,"secret"),DateTimeOffset.UtcNow.ToUnixTimeSeconds()/30)}));c.DefaultRequestHeaders.Authorization=new("Bearer",S(signed,"accessToken"));return c;
    }
    private static string Path(JsonNode p)=>"/api/admin/redirects/"+S(p,"redirectId");
    private static Task<JsonNode> Create(HttpClient c,string? source=null,string? target="/fa/catalog",int? status=301,bool demo=true)=>Send(c,"/api/admin/redirects/commands/"+Id(),new("Create",SourcePath:source??"/fa/pages/qa-"+Id(),IsDemo:demo,TargetPath:target,Status:status));
    private static async Task<JsonNode> Send(HttpClient c,string path,CmsRedirectWrite input)=>await Read(await c.PostAsJsonAsync(path,input));
    private static Task<JsonNode> Write(HttpClient c,JsonNode p,string action,string? target=null,int? status=null,string? restore=null)=>Send(c,Path(p)+"/commands/"+Id(),new(action,S(p,"version"),TargetPath:target,Status:status,RestoreRevisionId:restore,Confirmed:action!="Save"));
    private static string Resolve(string source)=>"/api/content/redirects/resolve?path="+Uri.EscapeDataString(source);
    [Fact]public async Task DraftStatusIsExplicitPublishRestoreUnpublishAndPublicProjectionAreIndependent(){
        using var staff=await Staff();using var anon=sql.Factory.CreateClient(new(){HandleCookies=false});var p=await Create(staff,target:null,status:null);var source=S(p,"sourcePath");var pub=Resolve(source);Assert.False((await Read(await anon.GetAsync(pub)))["found"]!.GetValue<bool>());var preview=await Read(await staff.GetAsync(Path(p)+"/preview"));Assert.False(preview["canPublish"]!.GetValue<bool>());Assert.Equal(2,preview["blockers"]!.AsArray().Count);
        using(var incomplete=await staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),new CmsRedirectWrite("Publish",S(p,"version"),Confirmed:true)))Assert.Equal(HttpStatusCode.Conflict,incomplete.StatusCode);
        p=await Write(staff,p,"Save","/fa/moments",302);p=await Write(staff,p,"Publish");var first=S(p,"revisionId");var resolved=await Read(await anon.GetAsync(pub));Assert.True(resolved["found"]!.GetValue<bool>());Assert.Equal(302,resolved["status"]!.GetValue<int>());Assert.DoesNotContain("actor",resolved.ToJsonString());Assert.DoesNotContain("draft",resolved.ToJsonString());await using(var scope=sql.Factory.Services.CreateAsyncScope())Assert.False((await new CmsRedirectService(scope.ServiceProvider.GetRequiredService<CmsDbContext>(),false).ResolveAsync(source,default)).Found);
        p=await Write(staff,p,"Save","/fa/catalog",301);Assert.Equal("/fa/moments",S(await Read(await anon.GetAsync(pub)),"targetPath"));p=await Write(staff,p,"Publish");p=await Write(staff,p,"Save","/fa/support",302);p=await Write(staff,p,"Restore",restore:first);var detail=await Read(await staff.GetAsync(Path(p)));Assert.Equal("/fa/support",S(detail["draft"]!,"targetPath"));Assert.Equal("/fa/moments",S(await Read(await anon.GetAsync(pub)),"targetPath"));p=await Write(staff,p,"Unpublish");Assert.False((await Read(await anon.GetAsync(pub)))["found"]!.GetValue<bool>());Assert.Equal(4,(await Read(await staff.GetAsync(Path(p)+"/history")))["items"]!.AsArray().Count);await Read(await staff.GetAsync("/api/admin/redirects"));await Read(await staff.GetAsync(Path(p)+"/revisions/"+first));await Read(await staff.GetAsync(Path(p)+"/commands/"+S(p,"commandId")));
    }
    [Fact]public async Task OppositeConcurrentPublicationsCannotCreateACycleAndAncestorsCannotExceedFiveHops(){
        using var staff=await Staff();var a="/fa/pages/cycle-a-"+Id();var b="/fa/pages/cycle-b-"+Id();var pa=await Create(staff,a,b);var pb=await Create(staff,b,a);var attempts=await Task.WhenAll(staff.PostAsJsonAsync(Path(pa)+"/commands/"+Id(),new CmsRedirectWrite("Publish",S(pa,"version"),Confirmed:true)),staff.PostAsJsonAsync(Path(pb)+"/commands/"+Id(),new CmsRedirectWrite("Publish",S(pb,"version"),Confirmed:true)));Assert.Single(attempts,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(attempts,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in attempts)if(r.IsSuccessStatusCode)await Read(r);else r.Dispose();
        var paths=Enumerable.Range(0,7).Select(_=>"/en/pages/chain-"+Id()).ToArray();for(var i=0;i<5;i++){var p=await Create(staff,paths[i],paths[i+1]);await Write(staff,p,"Publish");}var sixth=await Create(staff,paths[5],paths[6]);var preview=await Read(await staff.GetAsync(Path(sixth)+"/preview"));Assert.Contains("chain_too_long",preview["blockers"]!.AsArray().Select(x=>x!.GetValue<string>()));using var failed=await staff.PostAsJsonAsync(Path(sixth)+"/commands/"+Id(),new CmsRedirectWrite("Publish",S(sixth,"version"),Confirmed:true));Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);
    }
    [Fact]public async Task ReplayStaleVersionAndRootAuditFailureHaveNoPartialEffects(){
        using var staff=await Staff();var cmd=Id();var source="/fa/pages/atomic-"+Id();var input=new CmsRedirectWrite("Create",SourcePath:source,IsDemo:true,TargetPath:"/fa/catalog",Status:301);var path="/api/admin/redirects/commands/"+cmd;
        await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityDbContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_RedirectAudit CHECK ([Action]<>'CMS_REDIRECT_CREATE')");try{using var failed=await staff.PostAsJsonAsync(path,input);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityDbContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_RedirectAudit");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CmsDbContext>();Assert.False(await db.Redirects.AnyAsync(x=>x.SourcePath==source));Assert.False(await db.RedirectCommands.AnyAsync(x=>x.CommandId==cmd));}
        var attempts=await Task.WhenAll(staff.PostAsJsonAsync(path,input),staff.PostAsJsonAsync(path,input));var results=await Task.WhenAll(attempts.Select(Read));Assert.Single(results,x=>x["replayed"]!.GetValue<bool>());var p=results[0];using(var conflict=await staff.PostAsJsonAsync(path,input with{Status=302}))Assert.Equal(HttpStatusCode.Conflict,conflict.StatusCode);
        var write=new CmsRedirectWrite("Publish",S(p,"version"),Confirmed:true);var race=await Task.WhenAll(staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),write),staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),write));Assert.Single(race,x=>x.StatusCode==HttpStatusCode.OK);Assert.Single(race,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var r in race)if(r.IsSuccessStatusCode)await Read(r);else r.Dispose();await Read(await staff.GetAsync(path));
        await using var final=sql.Factory.Services.CreateAsyncScope();var cms=final.ServiceProvider.GetRequiredService<CmsDbContext>();Assert.Equal(1,await cms.RedirectRevisions.CountAsync(x=>x.RedirectId==S(p,"redirectId")));Assert.Equal(2,await cms.RedirectCommands.CountAsync(x=>x.RedirectId==S(p,"redirectId")));Assert.Equal(1,await final.ServiceProvider.GetRequiredService<IdentityDbContext>().Audit.CountAsync(x=>x.Resource==path));
    }
    [Fact]public async Task AuthorizationQueryOriginHistoryForeignKeysAndTamperingFailClosed(){
        using var staff=await Staff();using var other=await Staff();using var finance=await Staff("FinanceManager");using var anon=sql.Factory.CreateClient(new(){HandleCookies=false});var p=await Create(staff);p=await Write(staff,p,"Publish");var q=await Create(staff);q=await Write(staff,q,"Publish");
        using(var r=await anon.GetAsync(Path(p)))Assert.Equal(HttpStatusCode.Unauthorized,r.StatusCode);using(var r=await finance.GetAsync(Path(p)))Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);using(var r=await other.GetAsync(Path(p)+"/commands/"+S(p,"commandId")))Assert.Equal(HttpStatusCode.NotFound,r.StatusCode);using(var r=await staff.GetAsync(Path(p)+"/history?beforePublication=01"))Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);using(var r=await anon.GetAsync(Resolve(S(p,"sourcePath"))+"&x=1"))Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);using(var r=await staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),new{action="Publish",version=S(p,"version"),confirmed=true,paid=true}))Assert.Equal(HttpStatusCode.BadRequest,r.StatusCode);using(var r=await staff.PostAsJsonAsync(Path(p)+"/commands/"+Id(),new CmsRedirectWrite("Restore",S(p,"version"),RestoreRevisionId:S(q,"revisionId"),Confirmed:true)))Assert.Equal(HttpStatusCode.NotFound,r.StatusCode);
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CmsDbContext>();var revision=await db.RedirectRevisions.SingleAsync(x=>x.Id==S(p,"revisionId"));revision.Action="Restore";Assert.Equal("cms_redirect_immutable",Assert.Throws<BusinessException>(()=>db.SaveChanges()).Code);db.ChangeTracker.Clear();await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [cms].[Redirects] SET [PublishedRevisionId]={S(q,"revisionId")} WHERE [Id]={S(p,"redirectId")}"));await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>db.GetService<IMigrator>().MigrateAsync("20261027162533_CmsPages"));Assert.True(await db.Redirects.AnyAsync(x=>x.Id==S(p,"redirectId")));await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [cms].[RedirectRevisions] SET [FactsHash]={new string('0',64)} WHERE [Id]={S(p,"revisionId")}");}
        using(var r=await anon.GetAsync(Resolve(S(p,"sourcePath"))))Assert.Equal(HttpStatusCode.ServiceUnavailable,r.StatusCode);await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<CmsDbContext>().Database.ExecuteSqlInterpolatedAsync($"UPDATE [cms].[RedirectCommands] SET [ResultHash]={new string('0',64)} WHERE [CommandId]={S(p,"commandId")}");using(var r=await staff.GetAsync(Path(p)+"/commands/"+S(p,"commandId")))Assert.Equal(HttpStatusCode.ServiceUnavailable,r.StatusCode);
        staff.DefaultRequestHeaders.Remove("Origin");staff.DefaultRequestHeaders.Add("Origin","https://untrusted.example");using(var r=await staff.PostAsJsonAsync(Path(q)+"/commands/"+Id(),new CmsRedirectWrite("Publish",S(q,"version"),Confirmed:true)))Assert.Equal(HttpStatusCode.Forbidden,r.StatusCode);
    }
}
